    private static final Comparator<Timestamp> MOMENT = Comparator.nullsLast(Comparator.naturalOrder());

    /**
     * Legăturile NOI (pur): {@code istoricId} → {@code stripeTranzactieId}, în ordinea refundurilor ({@link LinkedHashMap}).
     * {@code toleranta} {@code null} ⇒ 0. Listele {@code null} ⇒ goale.
     */
    public static Map<Integer, Integer> leaga(List<RefundStripe> refunduri, List<RandIstoric> ramburs, BigDecimal toleranta) {
        Map<Integer, Integer> rez = new LinkedHashMap<>();
        if (refunduri == null || ramburs == null)
            return rez;
        BigDecimal tol = toleranta == null ? BigDecimal.ZERO : toleranta.abs();
        Set<Integer> dejaLegate = new HashSet<>();
        for (RandIstoric r : ramburs)
            if (r != null && r.stripeTranzactieId() > 0)
                dejaLegate.add(r.stripeTranzactieId());
        List<RefundStripe> rf = new ArrayList<>();
        for (RefundStripe x : refunduri)
            if (x != null && x.comandaSiteId() > 0 && x.brut() != null)
                rf.add(x);
        rf.sort(Comparator.comparing(RefundStripe::creatLa, MOMENT).thenComparingInt(RefundStripe::stripeTranzactieId));
        List<RandIstoric> cand = new ArrayList<>();
        for (RandIstoric r : ramburs)
            if (r != null && r.stripeTranzactieId() <= 0 && r.suma() != null)
                cand.add(r);
        cand.sort(Comparator.comparing(RandIstoric::modificatLaSursa, MOMENT).thenComparingInt(RandIstoric::istoricId));
        Set<Integer> refunduriFolosite = new HashSet<>(), randuriFolosite = new HashSet<>();
        for (RefundStripe x : rf) {
            if (dejaLegate.contains(x.stripeTranzactieId()) || !refunduriFolosite.add(x.stripeTranzactieId()))
                continue;
            BigDecimal suma = x.brut().abs();
            for (RandIstoric r : cand)
                if (r.comandaSiteId() == x.comandaSiteId() && !randuriFolosite.contains(r.istoricId())
                        && suma.subtract(r.suma().abs()).abs().compareTo(tol) <= 0) {
                    randuriFolosite.add(r.istoricId());
                    rez.put(r.istoricId(), x.stripeTranzactieId());
                    break;
                }
        }
        return rez;
    }
