    @Override
    protected String doIt() throws Exception {
        addLog(Etichete.t("corelare.import.parametri", operatie, nume, curier, primit, recordId, doarVerifica ? "Y" : "N"));
        Properties ctx = getCtx();
        int client = Env.getAD_Client_ID(ctx);
        if (REPARSEAZA.equals(operatie))
            return reparseaza(ctx, client);
        if (!IMPORTA.equals(operatie))
            throw new IllegalArgumentException(Etichete.t("corelare.proces.operatie_necunoscuta", operatie));
        byte[] date = Files.readAllBytes(fisierPermis(fisier));
        if (date.length > 25 * 1024 * 1024)
            throw new IllegalArgumentException(Etichete.t("corelare.import.prea_mare"));
        String sha = sha256(date);
        if (new Query(ctx, CorelareTabele.DECONT, "AD_Client_ID=? AND EVA_Sha256=?", get_TrxName()).setParameters(client, sha).count() > 0)
            return Etichete.t("corelare.import.exista");
        String numeCurat = PreiaDinSite.numeCuratat(nume == null || nume.isBlank() ? "decont" : nume);
        ProfilCurier.Clasificare cl = ProfilCurier.clasifica("", numeCurat);
        String cur = curier.isBlank() ? cl.curier() : curier;
        ParserDecont.Rezultat rez = ParserDecont.parseaza(numeCurat, date, "RON");
        String tip = ProfilCurier.NECUNOSCUT.equals(cl.tip()) ? tipDinStructura(rez) : cl.tip();
        if (doarVerifica)
            return Etichete.t("corelare.import.rezumat", numeCurat, Etichete.t("corelare.parsare." + rez.stare), rez.randuri.size(), tip)
                    + " " + Etichete.t("corelare.preia.doar_verifica");
        PO a = MTable.get(ctx, CorelareTabele.DECONT).getPO(0, get_TrxName());
        a.set_ValueNoCheck("AD_Client_ID", Integer.valueOf(client));
        a.set_ValueOfColumn("AD_Org_ID", 0);
        a.set_ValueOfColumn("EVA_Sursa", "FISIER");
        a.set_ValueOfColumn("EVA_Sha256", sha);
        a.set_ValueOfColumn("EVA_Curier", cur);
        a.set_ValueOfColumn("EVA_TipDocument", tip);
        a.set_ValueOfColumn("EVA_NumeFisier", PreiaDinSite.taie(numeCurat, 300));
        a.set_ValueOfColumn("EVA_DataPrimire", primit == null ? new Timestamp(System.currentTimeMillis()) : primit);
        a.set_ValueOfColumn("EVA_Moneda", PreiaDinSite.gol(PreiaDinSite.taie(rez.moneda, 8)));
        a.set_ValueOfColumn("EVA_StareParsare", rez.stare);
        a.set_ValueOfColumn("EVA_Eroare", PreiaDinSite.gol(PreiaDinSite.taie(rez.eroare, 500)));
        a.set_ValueOfColumn("EVA_NrRanduri", Integer.valueOf(rez.randuri.size()));
        a.set_ValueOfColumn("EVA_StareCorelare", ProfilCurier.RAMBURS_COMPENSAT.equals(tip) ? CorelareTabele.FARA_PLATA_COMPENSAT
                : CorelareTabele.NELEGAT);
        a.set_ValueOfColumn("EVA_ImportatLa", new Timestamp(System.currentTimeMillis()));
        verifica(a, CorelareTabele.DECONT);
        a.saveEx();
        scrieLinii(ctx, client, a, tip, rez.randuri, Map.of());
        MAttachment at = new MAttachment(ctx, a.get_Table_ID(), a.get_ID(), a.get_UUID(), get_TrxName());
        at.addEntry(numeCurat, date);
        at.saveEx();
        return Etichete.t("corelare.import.rezumat", numeCurat, Etichete.t("corelare.parsare." + rez.stare), rez.randuri.size(), tip);
    }

