const findings=[
row('A07-F01','Adaptorul comercial omite linia de expediție','RIDICAT','CONFIRMAT','Pe API cu drepturi și tenant reale, pentru linia comercială cunoscută metoda create_rma transmite produs+Qty fără M_InOutLine_ID. Prin model nativ, 2 au ajuns în CO la 1 livrat când lipsea linia; cu linie sursă, 2 au fost respinse. Procedura legitimă fără referință trebuie separată explicit.',['R1','API','PG','SUP'],'Folosește M_RMALine.M_InOutLine_ID după verificarea firmei, avizului și articolului. Definește separat returul autorizat fără sursă, cu motiv și rol.','1 livrat, 2 cerute; sursă din alt client; retur fără sursă permis versus interzis.','Nu a fost exercitat același request HTTP FastAPI direct cu ERP pornit în R2; niveluri separate transport și ERP.'),
row('A07-F02','Reluarea după refuz de linie creează un al doilea antet RMA','RIDICAT','CONFIRMAT','FastAPI injectat cu eroare după antet dă 500. La aceeași cheie, retry dă 201 și al doilea antet. După succes replay identic nu adaugă rânduri.',['API','R1'],'Preferă un SvrProcess tranzacțional pentru antet+linii, cu identificator de cerere persistent și unic pe cabinet, firmă și operație.','Eroare după antet, după prima linie, după CO/timeout; maximum un document pentru o singură cerere.','Persistența după eroare în R2 folosește transport CRUD simulat; scrierea individuală HTTP a clientului este demonstrată în cod identic cu imaginea.'),
row('A07-F03','Calea T22 utilizează aceeași locație pentru livrare și facturare','RIDICAT','CONFIRMAT_PE_CALE','Ambele settere primesc bp[1] (GeneratorDocumente.java 391/393). Coloane active distincte la native. Pe snapshot Garden nu a existat comandă de vânzare cu două valori diferite.',['R1','PG'],'Determină separat Ship-To și Bill-To, persistă pe C_Order și păstrează copia aferentă comenzii la import.','Adrese diferite, actualizare master după comandă, reimprimare și retur.','Nu măsoară ce canale invocă acest generator sau incidente de expediție din producție.'),
row('A07-F04','Politica de facturare târzie nu este respectată pe ramura examinată T22','RIDICAT','CONFIRMAT_CONDIȚIONAT','Culegere.dupaComplete(CO,false) => LIVRAT; generatorul apelează facturaSiLegaturi după CO și după faza 2. Nu există în acea decizie o confirmare de livrare de la curier. Faptul contează pentru canalele cu facturare târzie.',['R1','RC','PO'],'Folosește M_InOut pentru aviz și eveniment separat de livrare/incident, cu politica pe canal și C_Invoice generat exclusiv pentru liniile eligibile.','CO fără predare; livrare parțială; retur deschis și retry.','Reversarea furnizor și colet cu TrackingNo nu reprezintă confirmare POD.'),
row('A07-F05','Alocarea poate stinge plata pe o factură neeligibilă','RIDICAT','CONFIRMAT_EXTINS','GardenUser 103: DR/IP/VO => CO/E, plata alocată; factură CO => CO/Y; RE => CO/Y. Storno alocare RE/Y în toate cinci cazuri. R1 local confirmă CO/E 30 pe factură DR.',['AL','PG','R1'],'Validează în procesul nativ de alocare starea/semnul/soldul real al facturii și disponibilul plății în aceeași tranzacție; expune avans nealocat în UI.','DR/IP/VO/RE refuz conform operației, CO cu sold eligibil; retry și stornare în perioade diferite.','Reconcilierea plății nu garantează Posted=Y. Accesul tuturor rolurilor de producție nu a fost dedus.'),
row('A07-F06','Aceeași cheie de reluare dezvăluie ID-uri între cabinete cu același CUI','RIDICAT','NOU_CONFIRMAT_HTTP','Cabinet B cu CUI comun și aceeași cheie primește HTTP 201, RMA 11002 al cabinetului A și ID-ul liniei; către B nu se trimite cerere ERP. Cu cheie proprie B primește 21001. Niciun impact asupra datelor reale.',['API'],'Leagă idempotency de ID-ul imuabil al cabinetului, firmei, operației și cheii. Migrează intrările vechi cu domeniul verificabil, altfel nu le reutiliza.','Aceeași firmă atribuită la două cabinete, aceeași cheie; niciun replay încrucișat.','Este un test HTTP local al răspunsului, cu transport de documente simulat. Nu demonstrează citirea conținutului întregului RMA din alt cabinet.'),
row('A07-F07','Aprobarea cumulată concurentă depășește cantitatea expediată chiar cu linie sursă','RIDICAT','NOU_CONFIRMAT_NATIV','Pe aceeași linie 101 (livrat 2), două sesiuni au obținut CO de câte 2. Total autorizat 4, cantitatea primită încă zero. Martorul unic 3 a primit refuz. Distinct de F01.',['RC','SUP','R1'],'Sub blocarea liniei sursă, recitește suma deja autorizată și stările eligibile când eliberezi autorizația, în același proces/tranzacție. Menține documentele native și eliberarea prin stornare.','Două sesiuni 2+2 pe sursa 2; numai una primește CO. 1+1 este permis. Recepție ulterioară conservă cantitățile.','Nu s-a primit fizic cantitate 4 și nu s-a creditat o asemenea cantitate.'),
row('A07-F08','Reutilizarea cheii cu alt conținut returnează succes pentru cererea veche','MEDIU','NOU_CONFIRMAT_HTTP','După succes la Qty=2, aceeași cheie cu Qty=9 primește 201 și același ID fără nicio scriere. Idempotency verifică tenant, rută și cheie, nu amprenta datelor.',['API'],'Păstrează hashul unei reprezentări canonice a cererii; replay identic recuperează documentul iar payload diferit e refuzat explicit.','Qty diferit sau altă linie; eroare 409 fără efect și cu identificator de audit.','Această probă include numai ruta retururilor; alte rute cu același mecanism necesită control separat.')
