    /** FILTRU_NR_FACTURA: cel puțin o cifră ȘI cel mult 60 de caractere (identic cu SQL-ul conectorului). */
    public static boolean esteNrFactura(String x) {
        return x != null && x.length() <= 60 && x.chars().anyMatch(Character::isDigit);
    }

    /** CUI doar de persoană juridică: fără «RO» și spații; forma CNP (13 cifre) sau orice în afara a 2…10 cifre → "". */
    public static String cuiPersoanaJuridica(String s) {
        if (s == null)
            return "";
        String c = s.strip().toUpperCase(java.util.Locale.ROOT).replaceFirst("^RO", "").replaceAll("\\s+", "");
        if (c.matches("[0-9]{13}"))
            return "";
        return c.matches("[0-9]{2,10}") ? c : "";
    }

