    /** service.py:132-134 — AWB ≥ 15 caractere terminat în 3 cifre de colet. */
    public static boolean areSufixColet(String norm) {
        return norm != null && norm.length() >= 15 && norm.substring(norm.length() - 3).chars().allMatch(Character::isDigit);
    }

    /** O expediere candidată: id-ul și AWB-ul normalizat. */
