    }

    /**
     * service.py:160-180 — expedierile pentru un AWB de rând: întreg → «expediere fără sufix» → «rândul fără sufix»;
     * sufixul se taie DOAR pe partea mai lungă (niciodată trunchiat-vs-trunchiat); expedierea blocată manual e exclusă.
     */
    public static List<Integer> candidatiAwb(String awbRand, List<Exp> expedieri, int blocata) {
        Map<String, List<Integer>> peAwb = new LinkedHashMap<>(), faraSufix = new LinkedHashMap<>();
        for (Exp e : expedieri) {
            peAwb.computeIfAbsent(e.awbNorm(), k -> new ArrayList<>()).add(e.id());
            if (areSufixColet(e.awbNorm()))
                faraSufix.computeIfAbsent(e.awbNorm().substring(0, e.awbNorm().length() - 3), k -> new ArrayList<>()).add(e.id());
        }
        List<Integer> r = peAwb.get(awbRand);
        if (r == null)
            r = faraSufix.get(awbRand);
        if (r == null && areSufixColet(awbRand))
            r = peAwb.get(awbRand.substring(0, awbRand.length() - 3));
        List<Integer> out = new ArrayList<>();
        if (r != null)
            for (Integer id : new LinkedHashSet<>(r))
                if (id != blocata)
                    out.add(id);
        return out;
    }

