    public static String poarta(BigDecimal sumaLinie, String chargeLinie, boolean arePlata, List<String> tranzit,
            BigDecimal totalVirat, List<LinieD> linii, boolean lunaDeschisa) {
        BigDecimal tol = MotorCorelare.prag("TOL_SUMA");
