                sv = sv.add(l.virat());
        BigDecimal tv = totalVirat == null ? BigDecimal.ZERO : totalVirat;
        if (sumaLinie == null || sumaLinie.subtract(tv).abs().compareTo(tol) > 0)
            return Etichete.t("corelare.refuz.poarta_sold", sumaLinie, tv);
        if (sv.subtract(tv).abs().compareTo(tol) > 0)
