    private List<MotorCorelare.Exp> expedieri(int client, Set<String> dorite) throws Exception {
        List<MotorCorelare.Exp> l = new ArrayList<>();
        if (dorite.isEmpty())
            return l;
        String sql = "SELECT eva_expedieresite_id, eva_awbnorm FROM eva_expedieresite WHERE ad_client_id=? AND (eva_awbnorm = ANY(?)"
                + " OR (eva_awbnorm ~ '[0-9]{3}$' AND length(eva_awbnorm) >= 15 AND left(eva_awbnorm, length(eva_awbnorm)-3) = ANY(?)))";
        try (PreparedStatement ps = DB.prepareStatement(sql, get_TrxName())) {
            ps.setInt(1, client);
            java.sql.Array a = ps.getConnection().createArrayOf("text", dorite.toArray(new String[0]));
            ps.setArray(2, a);
            ps.setArray(3, a);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next())
                    l.add(new MotorCorelare.Exp(rs.getInt(1), rs.getString(2)));
            }
        }
        return l;
    }

