    }

    /** R3b: fără AWB, pe suma rambursului în [primire − 60, primire]; niciodată automat. */
    private MotorCorelare.Treapta r3b(int client, PO l, Set<Integer> rezervate) throws Exception {
        BigDecimal r = (BigDecimal) l.get_Value("EVA_Ramburs");
        if (r == null || r.signum() <= 0)
            return new MotorCorelare.Treapta(NELEGAT, "", 0, 0, Etichete.t("corelare.motiv.fara_awb"));
        Timestamp primit = DB.getSQLValueTSEx(get_TrxName(), "SELECT eva_dataprimire FROM eva_decontcurier WHERE eva_decontcurier_id=?",
                l.get_ValueAsInt("EVA_DecontCurier_ID"));
        List<Integer> ids = new ArrayList<>();
        String sql = "SELECT i.c_invoice_id FROM c_invoice i WHERE i.ad_client_id=? AND i.issotrx='Y' AND i.docstatus IN ('CO','CL')"
                + DOC_ARI + " AND abs(i.grandtotal - ?) <= ? AND i.dateinvoiced BETWEEN ? AND ?"
                + " AND NOT EXISTS (SELECT 1 FROM eva_decontcurierlinie x WHERE x.ad_client_id=i.ad_client_id AND x.c_invoice_id=i.c_invoice_id"
                + "   AND x.eva_starelegare IN ('LEGAT_AUTO','LEGAT_MANUAL','STINS')"
                + "   AND x.eva_decontcurierlinie_id<>?) ORDER BY i.dateinvoiced DESC, i.c_invoice_id LIMIT 20";
        try (PreparedStatement ps = DB.prepareStatement(sql, get_TrxName())) {
            ps.setInt(1, client);
            ps.setBigDecimal(2, r);

            int cmd = DB.getSQLValueEx(get_TrxName(), "SELECT COALESCE(eva_comandasite_id,0) FROM eva_expedieresite WHERE eva_expedieresite_id=?", exp);
            int inv = 0;
            if (cmd > 0) {
                monedaComanda = DB.getSQLValueStringEx(get_TrxName(), "SELECT COALESCE(eva_moneda,'') FROM eva_comandasite WHERE eva_comandasite_id=?", cmd);
                inv = DB.getSQLValueEx(get_TrxName(), "SELECT COALESCE(c_invoice_id,0) FROM eva_comandasite WHERE eva_comandasite_id=?"
                        + " AND eva_starelegare IN ('LEGAT_AUTO','LEGAT_MANUAL','STINS')", cmd);
            }
            MotorCorelare.Decontare d = decontare(l, monedaComanda);
            stare = MotorCorelare.CAUZE_BLOCANTE.contains(d.cauza()) ? DE_LAMURIT : LEGAT_AUTO;
            l.set_ValueOfColumn("EVA_ExpediereSite_ID", exp);
            l.set_ValueOfColumn("EVA_ComandaSite_ID", cmd > 0 ? Integer.valueOf(cmd) : null);
            l.set_ValueOfColumn("C_Invoice_ID", inv > 0 ? Integer.valueOf(inv) : null);
            l.set_ValueOfColumn("EVA_Regula", "R3");
            l.set_ValueOfColumn("EVA_Scor", BigDecimal.valueOf(3));
            l.set_ValueOfColumn("EVA_Motiv", taie(cmd <= 0 || inv <= 0 ? Etichete.t("corelare.motiv.comanda_nelegata")
                    : d.cauza().isEmpty() ? Etichete.t("corelare.motiv.awb_egal") : Etichete.t("corelare.cauza." + d.cauza()), 1000));
            if (inv > 0)
                rezervate.add(inv);
        } else if (cand.size() > 1) {
            decontare(l, "");
            stare = DE_LAMURIT;
    }

    private MotorCorelare.Decontare decontare(PO l, String monedaComanda) {
        MotorCorelare.Decontare d = MotorCorelare.evalueazaDecontare((BigDecimal) l.get_Value("EVA_Ramburs"),
                (BigDecimal) l.get_Value("EVA_SumaVirata"), (BigDecimal) l.get_Value("EVA_Compensat"),
                (BigDecimal) l.get_Value("EVA_Comision"), l.get_ValueAsString("EVA_Moneda"), monedaComanda);
        l.set_ValueOfColumn("EVA_Cauza", d.cauza().isEmpty() ? null : d.cauza());
        l.set_ValueOfColumn("EVA_Diferenta", d.diferenta());
        return d;
    }

