    /** «1, 2,3» → [1, 2, 3] (pur); un element nenumeric ⇒ {@link IllegalArgumentException} cu cheia. */
    public static List<Integer> ids(String s) {
        List<Integer> l = new ArrayList<>();
        if (s == null)
            return l;
        for (String x : s.split("[,;\\s]+")) {
            if (x.isBlank())
                continue;
            if (!x.strip().matches("[0-9]{1,10}"))
                throw new IllegalArgumentException(Etichete.t("vanzari.validare.inregistrari_invalide", x));
            l.add(Integer.valueOf(x.strip()));
        }
        return l;
    }

    /** Decizia {@code AUTO} pentru o comandă care trece (pură): {@code EMIT}, {@code RETIN} sau {@code PROPUN} (DE_APROBAT). */
    public enum DecizieAuto { EMIT, RETIN, PROPUN, ASTEAPTA_RETINERE }

    /**
     * Regula 49 §9.5.4 (b)/(d) și reținerea (pură): sub utilizatorul de serviciu, cu ambele moduri AUTOMAT ⇒ reținerea
     * &gt; 0 și comanda nereținută ⇒ {@code RETIN}; reținută și neexpirată ⇒ {@code ASTEAPTA_RETINERE}; altfel {@code EMIT};
     * orice altă combinație (om, MANUAL) ⇒ {@code PROPUN}.
     */
    public static DecizieAuto decizieAuto(boolean serviciu, boolean validareAutomat, boolean documenteAutomat, int retinere,
            String stareValidare, Timestamp retinutPanaLa, Timestamp acum) {
        if (!serviciu || !validareAutomat || !documenteAutomat)
            return DecizieAuto.PROPUN;
        if (DomeniiT22.IN_RETINERE.equals(stareValidare))
            return ModOperatie.retinereExpirata(retinutPanaLa, acum) ? DecizieAuto.EMIT : DecizieAuto.ASTEAPTA_RETINERE;
        return retinere > 0 ? DecizieAuto.RETIN : DecizieAuto.EMIT;
    }

    /** Starea comenzii după un val (pură): toate liniile {@code LIVRAT} / {@code EXCLUS} ⇒ {@code VALIDAT}, altfel {@code COADA}. */
    public static String stareDupaVal(List<String> stariLinii) {
        for (String s : stariLinii)
            if (!DomeniiT22.LIVRAT.equals(s) && !DomeniiT22.EXCLUS.equals(s))
                return DomeniiT22.COADA;
        return DomeniiT22.VALIDAT;
    }

